lane:
for lane in 1..POSEIDON2_WIDTH {
    let limbs = extension_limbs(state[lane]);
    state[lane] = extension_from_raw_limbs(core::array::from_fn(|limb| {
        full_sum[limb] + (u64::from(limbs[limb]) << SHIFTS[lane - 1])
    }));
}

cut:
if let Some(lane)=iter.next() {
    let limbs = extension_limbs(state[lane]);
    state[lane] = extension_from_raw_limbs(core::array::from_fn(|limb| {
        full_sum[limb] + (u64::from(limbs[limb]) << SHIFTS[lane - 1])
    }));
}
